from secret import flag

from Crypto.Util.number import *

assert len(flag) == 35
assert flag[:7] == b"moectf{"
assert flag[-1:] == b"}"


def main():
    p = getPrime(512)
    q = getPrime(512)

    n = p * q
    e = 65537

    m = bytes_to_long(flag)

    c = pow(m, e, n)
    hint = pow(p + q, 2, n)

    print(f"{n = }")
    print(f"{c = }")
    print(f"{hint = }")


if __name__ == "__main__":
    main()

